mapper.select:
SELECT #{producerId} AS producerId,
/* 오늘 매출: 실제 매출로 인정되는 상태들 */ ( SELECT NVL(SUM(oi.line_total_amount), 0) FROM ORDERS_ITEM oi JOIN PRODUCT p ON oi.product_id = p.product_id JOIN ORDERS o ON oi.order_id = o.order_id WHERE p.producer_id = #{producerId} AND TRUNC(o.created_date) = TRUNC(SYSDATE) AND oi.order_status IN ('A1', 'A2', 'E1', 'E2', 'E3') ) AS todaySalesAmount,
/* 이번달 매출 */ ( SELECT NVL(SUM(oi.line_total_amount), 0) FROM ORDERS_ITEM oi JOIN PRODUCT p ON oi.product_id = p.product_id JOIN ORDERS o ON oi.order_id = o.order_id WHERE p.producer_id = #{producerId} AND TRUNC(o.created_date, 'MM') = TRUNC(SYSDATE, 'MM') AND oi.order_status IN ('A1', 'A2', 'E1', 'E2', 'E3') ) AS monthSalesAmount,
/* 신규 주문 수 (오늘 / 진행 중 상태만) */ ( SELECT COUNT(DISTINCT o.order_id) FROM ORDERS_ITEM oi JOIN PRODUCT p ON oi.product_id = p.product_id JOIN ORDERS o ON oi.order_id = o.order_id WHERE p.producer_id = #{producerId} AND TRUNC(o.created_date) = TRUNC(SYSDATE) AND oi.order_status IN ('A1', 'B1') ) AS newOrderCount
FROM DUAL

mapper.update:

UPDATE ORDERS_ITEM oi
  SET oi.order_status = #{refundStatus}
WHERE oi.order_item_id = #{orderItemId}
  AND oi.product_id IN (
        SELECT p.product_id
          FROM PRODUCT p
          WHERE p.producer_id = #{producerId}
      )


UPDATE ORDERS o
  SET o.updated_date = SYSDATE
WHERE o.order_id = (
        SELECT oi.order_id
          FROM ORDERS_ITEM oi
          JOIN PRODUCT p
            ON oi.product_id = p.product_id
          WHERE oi.order_item_id = #{orderItemId}
            AND p.producer_id = #{producerId}
      )

mapper.select:
SELECT p.product_id AS productId, pd.detail_id AS detailId, p.name AS productName, p.base_category_id AS baseCategoryId, pd.grade AS grade, pd.unit_name AS unitName, pd.price AS price, pd.stock_qty AS stockQty, p.status AS status, pd.updated_date AS updatedDate FROM PRODUCT p JOIN PRODUCT_DETAIL pd ON p.product_id = pd.product_id WHERE p.producer_id = #{producerId}
AND p.status = #{status}
ORDER BY p.created_date DESC, p.product_id DESC, pd.detail_id ASC

mapper.delete:

DELETE FROM PRODUCT_IMAGE pi
WHERE pi.product_id = #{productId}
  AND EXISTS (
      SELECT 1
      FROM PRODUCT p
      WHERE p.product_id = pi.product_id
        AND p.producer_id = #{producerId}
  )


DELETE FROM PRODUCT_DETAIL pd
WHERE pd.product_id = #{productId}
  AND EXISTS (
      SELECT 1
      FROM PRODUCT p
      WHERE p.product_id = pd.product_id
        AND p.producer_id = #{producerId}
  )


DELETE FROM PRODUCT p
WHERE p.product_id = #{productId}
  AND p.producer_id = #{producerId}

